solution.Solution.cs:
public static class Brackets
{
    public static bool IsBalanced(string text)
    {
        var open = new Stack<char>();
        foreach (char c in text)
        {
            switch (c)
            {
                case '(' or '[' or '{':
                    open.Push(c);
                    break;
                case ')' or ']' or '}':
                    char expected = c == ')' ? '(' : c == ']' ? '[' : '{';
                    if (!open.TryPop(out char last) || last != expected) return false;
                    break;
            }
        }
        return open.Count == 0;
    }
}

unitTests:
Test("balanced", () =>
{
    foreach (var s in new[] { "", "()", "f(a[1], {b: 2})", "{[()()]}", "no brackets" })
        Check(Brackets.IsBalanced(s), s);
});

Test("unbalanced", () =>
{
    foreach (var s in new[] { "(]", "((", ")(", "{[}]", "]", "(()" })
        Check(!Brackets.IsBalanced(s), s);
});

